/**
 * @summary Get list of sent messages
 */
export const getGetSentMessagesUrl = () => {
  return `/api/messages/sent`;
};

export const getSentMessages = async (
  options?: RequestInit,
): Promise<SentMessagesResponse> => {
  return customFetch<SentMessagesResponse>(getGetSentMessagesUrl(), {
    ...options,
    method: "GET",
  });
};

export const getGetSentMessagesQueryKey = () => {
  return [`/api/messages/sent`] as const;
};

export const getGetSentMessagesQueryOptions = <
  TData = Awaited<ReturnType<typeof getSentMessages>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getSentMessages>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetSentMessagesQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getSentMessages>>> = ({
    signal,
  }) => getSentMessages({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getSentMessages>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetSentMessagesQueryResult = NonNullable<
  Awaited<ReturnType<typeof getSentMessages>>
>;
export type GetSentMessagesQueryError = ErrorType<unknown>;

/**
 * @summary Get list of sent messages
 */

export function useGetSentMessages<
  TData = Awaited<ReturnType<typeof getSentMessages>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<
    Awaited<ReturnType<typeof getSentMessages>>,
    TError,
    TData
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetSentMessagesQueryOptions(options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
